package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute mode : Integer := 0;
    attribute previousPressed : Boolean := false;
    attribute blinkState : Boolean := false;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign mode := (if ((mode) == (0)) ? 1 else (if ((mode) == (1)) ? 2 else 0));
      }
      then assign previousPressed := io_0;
      then if ((mode) == (1)) {
        first start;
        then assign blinkState := (not blinkState);
      } else {
        first start;
        then assign blinkState := false;
      }
    }
    out attribute io_1 : Boolean = (if ((mode) == (0)) ? false else (if ((mode) == (1)) ? blinkState else true));
  }
  part system : Controller;
}
